@extends('layouts.app')@section('title',$campaign->title)@section('content')<div class="wrap section"><div class="two"><div class="stack"><img class="cover" src="{{ $campaign->image_url }}" alt="Foto campaign"><div class="panel"><span class="tag">{{ $campaign->category }}</span><h1>{{ $campaign->title }}</h1><p class="muted">📍 {{ $campaign->location }} • Penggalang: {{ $campaign->user->name }}</p><p style="white-space:pre-line;line-height:1.8">{{ $campaign->description }}</p></div><div class="panel"><h2>Update Kegiatan</h2>@forelse($campaign->updates as $u)<h3>{{ $u->title }}</h3><small class="muted">{{ $u->created_at->format('d M Y') }}</small><p>{{ $u->body }}</p><hr>@empty<p>Belum ada update.</p>@endforelse</div><div class="panel"><h2>Laporan Penyaluran Dana</h2><div class="table-scroll"><table><tr><th>Tanggal</th><th>Keterangan</th><th>Nominal</th></tr>@foreach($campaign->expenses as $e)<tr><td>{{ $e->spent_at }}</td><td>{{ $e->title }} — {{ $e->description }}</td><td>Rp {{ number_format($e->amount,0,',','.') }}</td></tr>@endforeach</table></div><p>Total disalurkan: <b>Rp {{ number_format($campaign->expenses()->sum('amount'),0,',','.') }}</b></p></div>@auth @if(auth()->id()===$campaign->user_id || auth()->user()->role==='admin')<div class="panel"><h2>Kelola Campaign</h2><form method="POST" action="{{ route('manage.updates',$campaign) }}">@csrf<div class="field"><label>Judul Update</label><input name="title" required></div><div class="field"><label>Isi Update</label><textarea name="body" required></textarea></div><button class="btn">Terbitkan Update</button></form><hr><h3>Catat Pengeluaran</h3><form method="POST" action="{{ route('manage.expenses',$campaign) }}">@csrf<div class="field"><label>Judul</label><input name="title" required></div><div class="field"><label>Nominal (Rp)</label><input type="number" name="amount" min="1" required></div><div class="field"><label>Tanggal</label><input type="date" name="spent_at" required></div><div class="field"><label>Keterangan</label><textarea name="description"></textarea></div><button class="btn">Simpan Pengeluaran</button></form></div>@endif @endauth</div><aside><div class="panel"><h2>Donasi Sekarang</h2><h2 style="color:var(--red)">Rp {{ number_format($campaign->raised,0,',','.') }}</h2><div class="progress"><span style="width:{{ $campaign->percent }}%"></span></div><p class="muted">{{ $campaign->percent }}% dari Rp {{ number_format($campaign->target,0,',','.') }}</p><p>Deadline: {{ $campaign->deadline->format('d M Y') }}</p>@auth @if($campaign->status==='approved' && $campaign->deadline->endOfDay()->isFuture())<form method="POST" action="{{ route('donations.store',$campaign) }}">@csrf<div class="field"><label>Nominal (Rp)</label><input type="number" name="amount" value="100000" min="1000" required></div><div class="field"><label>Metode Pembayaran</label><select name="method"><option value="qris">QRIS (Simulasi)</option><option value="bank">Transfer Bank (Simulasi)</option><option value="ewallet">E-Wallet (Simulasi)</option></select></div><div class="field"><label>Pesan Dukungan</label><textarea name="message"></textarea></div><label><input type="checkbox" name="anonymous" value="1" style="width:auto"> Sembunyikan nama saya</label><br><br><button class="btn" style="width:100%">Lanjut Donasi →</button></form>@else<p>Donasi sedang tidak tersedia.</p>@endif<form method="POST" action="{{ route('favorite',$campaign) }}">@csrf<br><button class="btn outline" style="width:100%">♡ Simpan / Hapus Favorit</button></form>@else<a class="btn" href="{{ route('login') }}">Masuk untuk Berdonasi</a>@endauth</div></aside></div></div>@endsection
